-- Synthetic schema; fictitious institution and tokens only.
CREATE TABLE HT_ACCOUNT (ACCOUNT_ID CHAR(12) NOT NULL PRIMARY KEY, CUSTOMER_TOKEN CHAR(20) NOT NULL, BALANCE DECIMAL(11,2) NOT NULL, STATUS CHAR(8) NOT NULL, RATE DECIMAL(5,4) NOT NULL, LAST_ACTIVITY DATE NOT NULL);
CREATE INDEX HT_ACCOUNT_CUST_X ON HT_ACCOUNT(CUSTOMER_TOKEN);
CREATE TABLE HT_LEDGER (GL_ACCOUNT CHAR(10) NOT NULL, POST_DATE DATE NOT NULL, DEBIT DECIMAL(13,2) NOT NULL, CREDIT DECIMAL(13,2) NOT NULL, CURRENCY CHAR(3) NOT NULL);
CREATE TABLE HT_ACTIVITY (ACCOUNT_ID CHAR(12) NOT NULL, POST_DATE DATE NOT NULL, SEQUENCE_NO INTEGER NOT NULL, AMOUNT DECIMAL(11,2) NOT NULL, DETAIL CHAR(40), PRIMARY KEY(ACCOUNT_ID,POST_DATE,SEQUENCE_NO));
